  >(
    prefix: TPath,
    router: TChildRouter,
  ): Router<
    TInputContext,
    inferRouterContext<TChildRouter>,
    TMeta,
    Prefixer<TChildRouter['_def']['queries'], `${TPath}`> & TQueries,
    Prefixer<TChildRouter['_def']['mutations'], `${TPath}`> & TMutations,
